//! #30 hard-layout regression on the pinned runtime (own test binary: one PDFium load per
//! process). Fixture: `fixtures/library/layouts.pdf`, see `scripts/benchmarks/pdfgen.py`.
use cm_pdf::worker::*;
use std::{path::PathBuf, time::Duration};

/// #30 hard layouts on the pinned runtime: two columns, math (baseline shift + Symbol
/// font), a ruled table, vertical Japanese (Identity-V) and a rotated page. Every page is
/// also rendered once, so a layout cannot crash or hang the worker. The fixture is
/// generated by `scripts/generate_library_fixtures.py` (CC0, no embedded font program).
#[test]
fn hard_layout_text_and_render_on_the_pinned_runtime() {
    let library = PathBuf::from(
        std::env::var_os("CM_PDFIUM_LIBRARY")
            .expect("explicit pinned runtime fixture path required"),
    );
    let worker = PdfWorker::start(library).unwrap();
    let source = Source {
        path: PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/library/layouts.pdf")
            .canonicalize()
            .unwrap(),
        password: None,
    };
    let call = |operation| {
        worker
            .submit(operation, Cancellation::default(), Duration::from_secs(10))
            .unwrap()
            .wait(Duration::from_secs(12))
            .unwrap()
    };
    let batch = match call(Operation::Text {
        source: source.clone(),
        first_page: 0,
        max_pages: 64,
        max_chars: 100_000,
    }) {
        Output::Text(batch) => *batch,
        _ => panic!("expected text batch"),
    };
    assert_eq!(batch.page_count, 5);
    let page = |i: usize| batch.pages[i].text.as_str();
    let positions = |text: &str, lines: &[&str]| -> Vec<usize> {
        lines
            .iter()
            .map(|l| text.find(l).unwrap_or_else(|| panic!("{l:?} in {text:?}")))
            .collect()
    };
    let ordered = |at: &[usize]| at.windows(2).all(|w| w[0] < w[1]);
    // Two columns written column by column: each column's lines stay whole and in order.
    let left = positions(
        page(0),
        &[
            "LEFTCOL alpha one",
            "LEFTCOL alpha two",
            "LEFTCOL alpha three",
        ],
    );
    let right = positions(
        page(0),
        &[
            "RIGHTCOL beta one",
            "RIGHTCOL beta two",
            "RIGHTCOL beta three",
        ],
    );
    assert!(ordered(&left) && ordered(&right), "{:?}", page(0));
    // Math: the base line, the shifted superscript and Symbol glyphs as Unicode Greek.
    assert!(page(1).contains("Energy relation E = mc"), "{:?}", page(1));
    assert!(page(1).contains('2'));
    for greek in ['α', 'β', 'Σ', 'π'] {
        assert!(page(1).contains(greek), "{greek} in {:?}", page(1));
    }
    assert!(page(1).contains("numerator x") && page(1).contains("denominator y"));
    // Table: all nine cells, row-major.
    let cells: Vec<String> = (0..3)
        .flat_map(|r| (0..3).map(move |c| format!("Cell r{r}c{c}")))
        .collect();
    let at = positions(
        page(2),
        &cells.iter().map(String::as_str).collect::<Vec<_>>(),
    );
    assert!(ordered(&at), "{:?}", page(2));
    // Vertical Japanese (UniJIS-UCS2-V): each column is extracted whole and contiguous.
    // Observed on 8125: columns come out left to right (x ascending), i.e. opposite to the
    // right-to-left reading order, so only per-column contiguity is a search guarantee.
    let lines: Vec<&str> = page(3).lines().map(str::trim).collect();
    assert!(lines.contains(&"縦書きの日本語試験"), "{:?}", page(3));
    assert!(lines.contains(&"二列目の縦組"), "{:?}", page(3));
    assert!(page(3).contains("横書きの対照行です"), "{:?}", page(3));
    assert!(page(4).contains("ROTATED page marker ninety"));
    // Render every page (bitmap + character boxes) without error.
    for i in 0..5u32 {
        let snapshot = match call(Operation::Page {
            source: source.clone(),
            page_index: cm_domain::PageIndex::try_from(i).unwrap(),
            zoom: Some(1.0),
        }) {
            Output::Page(page) => *page,
            _ => panic!("expected page"),
        };
        let bitmap = snapshot.bitmap.expect("rendered bitmap");
        assert!(bitmap.width > 0 && bitmap.height > 0);
        assert!(!snapshot.characters.is_empty(), "page {i} has a text layer");
        // The rotated page renders landscape (595x842 portrait MediaBox, /Rotate 90).
        assert_eq!(bitmap.width > bitmap.height, i == 4, "page {i}");
    }
    worker.shutdown().unwrap();
}
